package net.muxigame.minigames.horseqa;
import com.google.gson.*;import net.muxigame.minigames.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.*;import net.neoforged.neoforge.event.tick.ServerTickEvent;import java.nio.file.*;
@EventBusSubscriber(modid="local_mc_debug_qa") public final class UmamusumeShopServerQA {static int ticks;@SubscribeEvent public static void tick(ServerTickEvent.Post e){if(!Boolean.getBoolean("muxi.horse.shopClientQa")||!"server".equals(System.getProperty("qa.local.role"))||++ticks%20!=0)return;for(var p:e.getServer().getPlayerList().getPlayers())if(p.getGameProfile().getName().equals("10000")){try{TrustedAccounts.admit(p);GameRuntime.get(e.getServer()).platform.refresh(p);var o=new JsonObject();o.addProperty("realNetworkPlayer",true);o.addProperty("uid",10000);o.addProperty("productionWrites",false);o.addProperty("scope","Private connected-player admission and read-only shop UI; no redemption");Files.writeString(Path.of(System.getProperty("qa.local.root")).resolve("shop-server-evidence.json"),o.toString());}catch(Throwable x){x.printStackTrace();}}}}
